def edit(path, pairs):
    s = open(path, encoding='utf-8').read()
    for old, new in pairs:
        assert s.count(old) == 1, (os.path.basename(path), s.count(old), old[:90])
        s = s.replace(old, new)
    open(path, 'w', encoding='utf-8').write(s)
    print('ok', os.path.basename(path), len(pairs))


